constraints:
0 ≤ n ≤ 10^{9}

expected time complexity: O(1)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def noConseBits(self, n: int) -> int:
		n = bin(n)[2:]
		i = 0
		b = n
		while i <= len(n):
			if n[i:i + 3] == '111':
				b = n[:i + 2] + '0' + n[i + 3:]
				n = b
			i += 1
		return int(n, 2)
